#pragma once

#include <cstdint>

#include "bmp581.hpp"
#include "HalI2cComm.h"
#include "HfResult.h"

namespace hf {

/// `bmp581::BusInterface` on a `BaseI2c`.
class HalI2cBmp581Comm final
    : public HalI2cComm<HalI2cBmp581Comm, bmp581::BusInterface<HalI2cBmp581Comm>> {
public:
    using HalI2cComm::HalI2cComm;
};

/**
 * @brief `hf::Status` for a Bmp581 driver error.
 *
 * Every enumerator is listed and there is no `default`, so an error the driver adds later is a
 * -Wswitch error here. The first draft came from tools/status_rules.py; review it against the driver.
 */
[[nodiscard]] constexpr Status ToStatus(bmp581::DriverError error) noexcept {
    switch (error) {
    case bmp581::DriverError::None:
        return Status::Ok;
    case bmp581::DriverError::InvalidParameter:
        return Status::InvalidArgument;
    case bmp581::DriverError::NotInitialized:
        return Status::NotInitialized;
    case bmp581::DriverError::Bus:
        return Status::Bus;
    case bmp581::DriverError::InvalidChipId:
        return Status::NotFound;
    case bmp581::DriverError::NvmNotReady:
        return Status::Busy;
    case bmp581::DriverError::PorSoftReset:
        return Status::Fault;
    case bmp581::DriverError::InvalidPowerMode:
        return Status::InvalidArgument;
    case bmp581::DriverError::NvmInvalidAddr:
        return Status::InvalidArgument;
    case bmp581::DriverError::NvmCommandError:
        return Status::Fault;
    }
    return Status::Unknown;
}

/// A driver result as an `hf::Result`; the driver's error value is the detail.
template <typename T>
[[nodiscard]] inline Result<T> ToResult(const bmp581::DriverResult<T>& result) noexcept {
    if (result.ok()) {
        return result.value;
    }
    return Fail(ToStatus(result.error), static_cast<std::uint32_t>(result.error));
}

/// A driver result without a value as an `hf::Result<void>`.
[[nodiscard]] inline Result<void> ToResult(const bmp581::DriverResult<void>& result) noexcept {
    if (result.ok()) {
        return {};
    }
    return Fail(ToStatus(result.error), static_cast<std::uint32_t>(result.error));
}

}  // namespace hf
